// Tidy the lead and decide whether it can go any further.
//
// The email address is the one field the pipeline cannot work without: it is
// how a lead is deduplicated against the CRM and how anyone replies. A lead
// without one is not dropped - it goes to quarantine for a human.

const EMAIL = /^[^@\s]+@[^@\s.]+\.[^@\s]+$/;

return $input.all().map((item) => {
  // A caller may hand us the lead directly, or wrapped in an HTTP envelope
  // (`body`) when something posts to this workflow over a webhook.
  const envelope = item.json || {};
  const raw = envelope.body && typeof envelope.body === 'object'
    ? { ...envelope, ...envelope.body }
    : envelope;
  const lead = raw.lead || raw;

  const email = String(lead.email || '').trim().toLowerCase();
  const valid = EMAIL.test(email);

  return {
    json: {
      // Settings travel with the lead so later nodes can read them.
      criteria_doc_id: raw.criteria_doc_id,
      sheet_id: raw.sheet_id,
      telegram_chat_id: raw.telegram_chat_id,
      has_email: valid,
      lead: {
        // n8n's Code sandbox has no `crypto`, so the id is built from the
        // clock plus randomness - unique enough to trace one lead through
        // the sheet, the CRM and the logs.
        lead_id: lead.lead_id || `lead_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`,
        received_at: lead.received_at || new Date().toISOString(),
        source: lead.source || 'unknown',
        source_detail: lead.source_detail || '',
        first_name: String(lead.first_name || '').trim(),
        last_name: String(lead.last_name || '').trim(),
        email,
        phone: String(lead.phone || '').trim(),
        company: String(lead.company || '').trim(),
        website: String(lead.website || '').trim(),
        office_size_sqft: Number(lead.office_size_sqft) || null,
        cleaning_frequency: String(lead.cleaning_frequency || '').trim(),
        city: String(lead.city || '').trim(),
        message: String(lead.message || '').trim(),
        raw: lead.raw || raw,
      },
    },
  };
});

// Google returns a document as a tree of styled runs, not as text.
// The model only needs the words, so the tree is flattened here.

function toPlainText(doc) {
  const parts = [];
  for (const block of doc?.body?.content || []) {
    for (const element of block.paragraph?.elements || []) {
      if (element.textRun?.content) parts.push(element.textRun.content);
    }
    // A table of thresholds would otherwise vanish silently.
    for (const row of block.table?.tableRows || []) {
      for (const cell of row.tableCells || []) {
        for (const inner of cell.content || []) {
          for (const element of inner.paragraph?.elements || []) {
            if (element.textRun?.content) parts.push(element.textRun.content);
          }
        }
      }
    }
  }
  return parts.join('').replace(/\n{3,}/g, '\n\n').trim();
}

// n8n's Google Docs node already hands back plain text in `content`. The
// tree-walker above is the fallback for a raw Docs API response, which is
// what you get from an HTTP Request node instead of this one.
const doc = $input.first().json || {};
const criteria = typeof doc.content === 'string' && doc.content.trim()
  ? doc.content.trim()
  : toPlainText(doc);

if (criteria.length < 50) {
  // Scoring against an empty document would quietly give every lead the same
  // score, which is worse than stopping.
  throw new Error('The scoring criteria document is empty or could not be read.');
}

// Carry the lead forward alongside the criteria.
return $('Check the lead').all().map((item) => ({
  json: { ...item.json, criteria },
}));

parameters.inputSchema:
{
  "type": "object",
  "required": ["score", "tier", "reason", "suggested_next_action"],
  "properties": {
    "score": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "How good this lead is, using the criteria's bands"
    },
    "tier": {
      "type": "string",
      "enum": ["hot", "warm", "cold"],
      "description": "Must match the score using the thresholds in the criteria"
    },
    "reason": {
      "type": "string",
      "description": "One sentence quoting real details from this lead"
    },
    "suggested_next_action": {
      "type": "string",
      "description": "One short instruction for whoever picks the lead up"
    }
  }
}

